    display: 'flex',
    gap: '10px',
    marginTop: '20px'
  },
  submitBtn: {
    backgroundColor: '#10b981',
    color: 'white',
    border: 'none',
    padding: '10px 20px',
    borderRadius: '6px',
    cursor: 'pointer'
  },
  cancelBtn: {
    backgroundColor: '#6b7280',
    color: 'white',
    border: 'none',
    padding: '10px 20px',
    borderRadius: '6px',
    cursor: 'pointer'
  },
  emptyState: {
    textAlign: 'center',
    padding: '60px 20px',
    backgroundColor: 'white',
    borderRadius: '10px'
  },
  emptyIcon: {
    fontSize: '48px',
    display: 'block',
    marginBottom: '20px'
  },
